#include <string>
#include <string_view>

class Printer
{
public:
    std::string show(int value) const { return "int " + std::to_string(value); }
    std::string show(bool value) const { return value ? "yes" : "no"; }
};

class FancyPrinter : public Printer
{
public:
    using Printer::show;
    std::string show(std::string_view text) const { return "<<" + std::string{ text } + ">>"; }
};
